const originalPlan=referencePlan,originalTripDetails=referenceTrip,originalLive=liveRouteView;
let planMode='map',geoMap=null,geoLayers=null,pickTarget='from',places={from:null,to:null},queries={from:'',to:''},searchResults=[],searchTarget='from',searchMessage='',searchBusy=false,searchVersion=0,searchTime=0,searchCache=new Map(),mapOptions=[],mapChoice=0,mapSearched=false,mapPreference='distance',journeyTimer=null,journeyRunning=false,journeySpeed=1;
const MAP_CONFIG={search:'https://photon.komoot.io/api/',tiles:'https://tile.openstreetmap.org/{z}/{x}/{y}.png'};
const normalizePlace=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const distanceKm=(a,b)=>{const r=Math.PI/180;return 12742*Math.asin(Math.min(1,Math.sqrt(Math.sin((b[0]-a[0])*r/2)**2+Math.cos(a[0]*r)*Math.cos(b[0]*r)*Math.sin((b[1]-a[1])*r/2)**2)))};
const distanceLabel=k=>k<1?Math.round(k*1000)+' m':k.toFixed(1)+' km';
function flowNav(active){return `<div class="flow-nav"><button class="${active==='plan'?'selected':''}" onclick="go('plan')"><b>1</b> Planifica</button><span>›</span><button class="${active==='trip'?'selected':''}" onclick="go('trip')"><b>2</b> Sigue tu viaje${data.active?' ●':''}</button><button class="catalog-link ${active==='live'?'selected':''}" onclick="go('live')">Rutas y horarios</button></div>`}
function setPlanMode(mode){planMode=mode;render()}
function addressField(key,title){return `<div class="address-field"><label for="address-${key}">${title}</label><div class="address-input"><span class="address-dot ${key}"></span><input id="address-${key}" value="${esc(queries[key])}" placeholder="Dirección, lugar o estación en Lima" autocomplete="off" oninput="editAddress('${key}',this.value)" onkeydown="if(event.key==='Enter'){event.preventDefault();lookupAddress('${key}')}"><button aria-label="Buscar ${key==='from'?'origen':'destino'}" onclick="lookupAddress('${key}')" ${searchBusy?'disabled':''}>${icon('search')}</button></div><div class="row between"><button class="text-btn" onclick="pickTarget='${key}';mapHint()">Elegir en el mapa</button><small id="confirmed-${key}" class="confirmed">${places[key]?'✓ Ubicación elegida':''}</small></div></div>`}
function editAddress(key,value){queries[key]=value;places[key]=null;searchVersion++;searchResults=[];mapOptions=[];mapSearched=false;document.getElementById('confirmed-'+key).textContent='';document.getElementById('map-options').innerHTML='';document.getElementById('address-results').innerHTML='';document.getElementById('build-route').disabled=true;drawMap()}
function addressResultView(){if(searchBusy)return '<p role="status">Buscando lugares…</p>';if(searchMessage)return `<p class="search-message" role="status">${esc(searchMessage)}</p>`;return `<div class="address-results">${searchResults.map((p,i)=>`<button onclick="selectAddress(${i})">${icon('pin')}<span><strong>${esc(p.name)}</strong><small>${esc(p.detail||'Ubicación de referencia')}</small></span></button>`).join('')}</div>`}
async function lookupAddress(key){if(searchBusy)return;const q=queries[key].trim();searchMessage='';searchResults=[];searchTarget=key;if(q.length<3){searchMessage='Escribe al menos 3 caracteres o marca un punto en el mapa.';render();return}const local=Object.entries(STATION_GEO).filter(([n])=>normalizePlace(n).includes(normalizePlace(q))).map(([name,coords])=>({name,coords,detail:'Estación del Metropolitano · punto de referencia OSM'}));if(local.length){searchResults=local;render();return}if(Date.now()-searchTime<1500){searchMessage='Espera un momento antes de volver a buscar.';render();return}searchTime=Date.now();searchBusy=true;const version=++searchVersion;render();const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),12000);
try{let features=searchCache.get(q);if(!features){const url=new URL(MAP_CONFIG.search);url.search=new URLSearchParams({q:/^utec\b/i.test(q)?'Universidad de Ingeniería y Tecnología':q,lat:'-12.05',lon:'-77.04',bbox:'-77.2,-12.3,-76.8,-11.8',limit:'6'});const res=await fetch(url,{signal:controller.signal});if(!res.ok)throw Error('search');features=(await res.json()).features||[];searchCache.set(q,features)}if(version!==searchVersion)return;searchResults=features.filter(f=>f.geometry?.type==='Point'&&f.geometry.coordinates[0]>=-77.2&&f.geometry.coordinates[0]<=-76.8&&f.geometry.coordinates[1]>=-12.3&&f.geometry.coordinates[1]<=-11.8).map(f=>{const p=f.properties;return {name:p.name||[p.street,p.housenumber].filter(Boolean).join(' ')||q,coords:[f.geometry.coordinates[1],f.geometry.coordinates[0]],detail:[p.street,p.housenumber,p.district||p.city,p.state].filter(Boolean).join(', ')}});if(!searchResults.length)searchMessage='No encontramos ese lugar. Añade el distrito o elige un punto en el mapa.'}catch(e){if(version===searchVersion)searchMessage='La búsqueda no está disponible ahora. Puedes buscar una estación por nombre o elegir un punto en el mapa.'}finally{clearTimeout(timeout);searchBusy=false;if(page==='plan')render()}}
function selectAddress(i){if(!searchResults[i])return;places[searchTarget]=searchResults[i];queries[searchTarget]=places[searchTarget].name;pickTarget=searchTarget==='from'?'to':'from';searchResults=[];searchMessage='';mapOptions=[];mapSearched=false;render()}
function selectMapPoint(coords,name){if(coords[0]<-12.3||coords[0]>-11.8||coords[1]<-77.2||coords[1]>-76.8)return toast('Elige un punto en Lima o Callao.');places[pickTarget]={name:name||'Punto en el mapa',coords};queries[pickTarget]=name||'Punto: '+coords.map(n=>n.toFixed(4)).join(', ');pickTarget=pickTarget==='from'?'to':'from';searchVersion++;searchResults=[];searchMessage='';mapOptions=[];mapSearched=false;render()}
function mapHint(){const el=document.getElementById('map-hint');if(el)el.textContent='Toca el mapa para elegir '+(pickTarget==='from'?'tu origen':'tu destino');document.querySelectorAll('[data-pick]').forEach(el=>el.classList.toggle('selected',el.dataset.pick===pickTarget))}
const pathCache=new Map();
function stationPath(a,b){const key=a+'|'+b;if(pathCache.has(key))return pathCache.get(key);if(a===b)return [a];const adj={};Object.keys(STATION_GEO).forEach(n=>adj[n]=[]);for(const r of TRANSIT_CATALOG.filter(r=>['A','B','C','D'].includes(r.id)))for(const dir of ['south','north'])r[dir].forEach((n,i)=>{if(i&&adj[n]&&adj[r[dir][i-1]])adj[r[dir][i-1]].push(n)});const d={[a]:0},prev={},seen=new Set();while(true){const n=Object.keys(d).filter(n=>!seen.has(n)).sort((x,y)=>d[x]-d[y])[0];if(!n)break;if(n===b){const path=[b];while(prev[path[0]])path.unshift(prev[path[0]]);pathCache.set(key,path);return path}seen.add(n);for(const next of adj[n]||[]){const nd=d[n]+distanceKm(STATION_GEO[n],STATION_GEO[next]);if(d[next]===undefined||nd<d[next]){d[next]=nd;prev[next]=n}}}return [a,b]}
function legCoordinates(leg){return leg.stops.flatMap((s,i)=>i?stationPath(leg.stops[i-1],s).slice(1):[s]).filter(s=>STATION_GEO[s]).map(s=>STATION_GEO[s])}
function routeKm(route){return route.legs.reduce((total,l)=>{const pts=legCoordinates(l);return total+pts.reduce((s,p,i)=>s+(i?distanceKm(pts[i-1],p):0),0)},0)}
function compareMapRoutes(a,b){return mapPreference==='walk'?a.walkKm-b.walkKm||a.totalKm-b.totalKm:mapPreference==='changes'?a.transfers-b.transfers||a.totalKm-b.totalKm:a.totalKm-b.totalKm||a.transfers-b.transfers}
function calculateMapRoutes(){if(!places.from||!places.to)return;mapSearched=true;mapChoice=0;searchMessage='';searchResults=[];mapOptions=[];if(distanceKm(places.from.coords,places.to.coords)<.05){searchMessage='Origen y destino están en el mismo lugar. No necesitas un bus.';render();return}const nearby=p=>Object.entries(STATION_GEO).map(([name,c])=>({name,d:distanceKm(p,c)})).filter(x=>x.d<=2).sort((a,b)=>a.d-b.d).slice(0,4);const starts=nearby(places.from.coords),ends=nearby(places.to.coords),oldNetwork=planNetwork,all=[];planNetwork='metro';for(const a of starts)for(const b of ends){if(a.name===b.name)continue;for(const r of findJourneys(a.name,b.name,'all')){const transitKm=routeKm(r),walkKm=a.d+b.d;all.push({...r,accessFrom:places.from,accessTo:places.to,walkFrom:a.d,walkTo:b.d,walkKm,transitKm,totalKm:transitKm+walkKm})}}planNetwork=oldNetwork;const unique=new Map();for(const r of all.sort(compareMapRoutes)){const key=r.origin+'|'+r.destination+'|'+r.legs.map(l=>l.routeId).join();if(!unique.has(key))unique.set(key,r)}mapOptions=[...unique.values()].slice(0,3);if(!starts.length||!ends.length)searchMessage='Un punto está a más de 2 km de las estaciones del mapa. Prueba otra ubicación o planifica un corredor por paradas.';render()}
function mapResultsView(){if(!mapSearched)return `<div class="map-empty">${icon('route')}<h3>Tu próximo viaje empieza aquí</h3><p>Elige origen y destino para comparar estaciones y servicios cercanos.</p></div>`;if(!mapOptions.length)return `<section class="card"><h3>No encontramos un recorrido</h3><p>${esc(searchMessage||'No hay conexión entre estos puntos en el catálogo cargado.')}</p><button class="secondary full" onclick="setPlanMode('stops')">Buscar por paradas</button></section>`;return `<h3>${mapOptions.length} opciones para ti</h3>${mapOptions.map((r,i)=>`<button class="card route-card ${mapChoice===i?'selected':''}" aria-pressed="${mapChoice===i}" onclick="mapChoice=${i};render()"><div class="row between"><strong>${r.legs.map(l=>l.name).join(' → ')}</strong><span class="pill teal">${i?'Alternativa':mapPreference==='distance'?'Menor recorrido':mapPreference==='walk'?'Menos acceso a pie':'Menos cambios'}</span></div><div class="route-metrics"><strong>${distanceLabel(r.totalKm)}<small>recorrido estimado</small></strong><strong>${r.transfers}<small>transbordos</small></strong><strong>${distanceLabel(r.walkKm)}<small>accesos en línea recta</small></strong></div><p>${esc(r.origin)} → ${esc(r.destination)}</p><small>${r.transfers?'Cambio en '+esc(r.legs[0].to):'Sin cambiar de bus'}</small></button>`).join('')}<button class="primary full" onclick="lastRoute=mapOptions[mapChoice];go('trip')">Ver pasos e iniciar viaje →</button><p class="small muted">Comparamos hasta 4 estaciones cercanas por extremo y un transbordo. Es el menor recorrido estimado entre estas opciones, no una garantía de la ruta más corta de Lima. Confirma horarios antes de viajar.</p>`}
referencePlan=function(){const tabs=`<div class="mode-tabs"><button class="${planMode==='map'?'selected':''}" onclick="setPlanMode('map')">${icon('pin')} Dirección o mapa</button><button class="${planMode==='stops'?'selected':''}" onclick="setPlanMode('stops')">${icon('bus')} Por paradas</button></div>`;if(planMode==='stops')return flowNav('plan')+tabs+originalPlan();return flowNav('plan')+heading('¿A dónde vamos?','Elige tus puntos en Lima. Conectamos las estaciones de tu recorrido.')+tabs+`<div class="map-planner"><div class="stack"><section class="card address-card">${addressField('from','¿Dónde empiezas?')}<button class="swap-places" aria-label="Intercambiar ubicaciones" onclick="[places.from,places.to]=[places.to,places.from];[queries.from,queries.to]=[queries.to,queries.from];mapOptions=[];mapSearched=false;render()">${icon('swap')}</button>${addressField('to','¿A dónde quieres llegar?')}<div id="address-results">${addressResultView()}</div><label class="spaced" for="map-preference">Prioriza tu recorrido</label><select id="map-preference" onchange="mapPreference=this.value;if(mapSearched)calculateMapRoutes()">${[['distance','Menor distancia estimada'],['walk','Menor distancia a pie'],['changes','Menos transbordos']].map(([v,n])=>`<option value="${v}" ${v===mapPreference?'selected':''}>${n}</option>`).join('')}</select><button id="build-route" class="primary full spaced" onclick="calculateMapRoutes()" ${!places.from||!places.to?'disabled':''}>Buscar mi recorrido →</button><p class="small muted">Al pulsar la lupa, el texto se consulta en Photon / OpenStreetMap. No usamos tu GPS.</p></section><div id="map-options" class="stack">${mapResultsView()}</div></div><div class="stack map-column"><section class="card geographic-card"><div class="map-toolbar"><button data-pick="from" class="chip" onclick="pickTarget='from';mapHint()">A · Origen</button><button data-pick="to" class="chip" onclick="pickTarget='to';mapHint()">B · Destino</button><button class="text-btn" onclick="fitMap()">Centrar mapa</button></div><p id="map-hint" class="small muted"></p><div id="journey-map" role="region" aria-label="Mapa de Lima para elegir origen y destino"></div><div class="map-legend"><span>━ Metropolitano</span><span>┄ Acceso aproximado</span></div></section><div class="coverage-note"><strong>Mapa del Metropolitano</strong><p>Los corredores están en «Por paradas». Las líneas unen puntos de referencia, no calles exactas. Los accesos se miden en línea recta; no son navegación peatonal.</p></div>${data.active?'<button class="primary full" onclick="go(\'trip\')">Volver a mi viaje en curso →</button>':''}</div></div>`};
function mountMap(){if(page!=='plan'||planMode!=='map')return;const el=document.getElementById('journey-map');if(!el)return;if(typeof L==='undefined'){el.innerHTML='<p class="map-empty">No se pudo cargar el mapa. Puedes planificar por paradas.</p>';return}geoMap=L.map(el,{scrollWheelZoom:false}).setView([-12.065,-77.04],12);L.tileLayer(MAP_CONFIG.tiles,{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors'}).on('tileerror',()=>{const hint=document.getElementById('map-hint');if(hint)hint.textContent='El fondo del mapa no está disponible. Busca una dirección o utiliza las estaciones.'}).addTo(geoMap);geoMap.on('click',e=>selectMapPoint([e.latlng.lat,e.latlng.lng]));geoLayers=L.layerGroup().addTo(geoMap);drawMap();mapHint();fitMap()}
function drawMap(){if(!geoMap||!geoLayers)return;geoLayers.clearLayers();for(const r of TRANSIT_CATALOG.filter(r=>['A','B','C','D'].includes(r.id)))L.polyline(r.south.filter(n=>STATION_GEO[n]).map(n=>STATION_GEO[n]),{color:'#7b8da5',weight:3,opacity:.6}).addTo(geoLayers);for(const [name,coords] of Object.entries(STATION_GEO))L.circleMarker(coords,{radius:4,color:'#174c95',weight:2,fillColor:'white',fillOpacity:1,bubblingMouseEvents:false}).bindTooltip(esc(name)).on('click',()=>selectMapPoint(coords,name)).addTo(geoLayers);const r=mapOptions[mapChoice];if(r){for(const l of r.legs)L.polyline(legCoordinates(l),{color:TRANSIT_CATALOG.find(x=>x.id===l.routeId).color,weight:7}).addTo(geoLayers);for(const [p,s] of [[places.from,r.origin],[places.to,r.destination]])L.polyline([p.coords,STATION_GEO[s]],{color:'#e36a24',weight:3,dashArray:'6 7'}).addTo(geoLayers)}for(const [k,p] of Object.entries(places)){if(p)L.marker(p.coords,{icon:L.divIcon({className:'geo-pin '+k,html:k==='from'?'A':'B',iconSize:[32,32],iconAnchor:[16,32]})}).bindTooltip(esc(p.name)).addTo(geoLayers)}}
function fitMap(){if(!geoMap)return;const pts=Object.values(places).filter(Boolean).map(p=>p.coords);if(mapOptions[mapChoice])pts.push(...mapOptions[mapChoice].legs.flatMap(legCoordinates));if(pts.length>1)geoMap.fitBounds(pts,{padding:[30,30],maxZoom:15});else if(pts.length)geoMap.setView(pts[0],15)}
function journeyStops(r){const stops=[];r.legs.forEach((l,li)=>l.stops.forEach((name,i)=>{if(li&&i===0){stops.at(-1).transfer=l.name;return}stops.push({name,line:l.name})}));return stops}
function progressState(r){const stops=journeyStops(r),progress=Math.max(0,Math.min(1,r.progress||0)),position=progress*(stops.length-1);return {stops,progress,position,index:Math.min(stops.length-1,Math.floor(position+1e-8))}}
function journeyMap(r){const ss=journeyStops(r),pts=ss.map((_,i)=>simPoint(i,ss.length));return `<div class="simulation-map journey-map"><svg viewBox="0 0 390 480" role="img" aria-label="Avance simulado de tu trayecto"><rect width="390" height="480" fill="#edf2f9"/><path d="M0 180Q110 300 40 480H0Z" fill="#c2daf1"/><text x="18" y="28" fill="#455b78" font-size="12">TU TRAYECTO · ESQUEMA SIN GPS</text><polyline points="${pts.map(p=>p.x+','+p.y).join(' ')}" fill="none" stroke="#b2bfd0" stroke-width="7"/><polyline id="journey-line" fill="none" stroke="#0b5aa8" stroke-width="7"/>${pts.map((p,i)=>`<circle data-journey-dot="${i}" cx="${p.x}" cy="${p.y}" r="5" fill="white" stroke="#607790" stroke-width="2"/>`).join('')}<text x="${pts[0].x+15}" y="64" fill="#172e4e" font-size="11">${esc(ss[0].name)}</text><text x="${pts.at(-1).x+12}" y="445" fill="#172e4e" font-size="11">${esc(ss.at(-1).name)}</text><g id="journey-bus"><circle r="22" fill="#1653ad" opacity=".2"/><rect x="-14" y="-14" width="28" height="28" rx="7" fill="#1653ad" stroke="white" stroke-width="2"/><rect x="-9" y="-9" width="18" height="11" rx="2" fill="#dceefc"/><circle cx="-7" cy="8" r="2" fill="white"/><circle cx="7" cy="8" r="2" fill="white"/></g></svg><span class="sim-tag">Movimiento simulado</span></div>`}
function activeJourneyView(r){const {stops}=progressState(r);return flowNav('trip')+heading('Tu viaje, paso a paso.',esc(r.origin)+' → '+esc(r.destination))+`<div class="journey-grid"><div class="stack"><section class="card journey-status"><span class="pill teal">VIAJE DE DEMOSTRACIÓN</span><h2 id="journey-status" class="spaced"></h2><p id="journey-next"></p><div class="progress-track"><span id="journey-bar"></span></div><div class="row between small"><span id="journey-count"></span><span id="journey-percent"></span></div><div id="journey-alert" class="arrival-alert" role="status"></div><div class="track-controls"><button id="journey-play" class="primary" onclick="journeyRunning=!journeyRunning;save();this.textContent=journeyRunning?'Pausar simulación':'Continuar simulación'">${journeyRunning?'Pausar simulación':'Continuar simulación'}</button><button id="journey-next-button" class="secondary" onclick="nextJourneyStop()">Siguiente parada →</button><select aria-label="Velocidad de simulación del viaje" onchange="journeySpeed=Number(this.value)">${[1,2,4].map(n=>`<option value="${n}" ${journeySpeed===n?'selected':''}>${n}×</option>`).join('')}</select></div><p class="small muted">El progreso se guarda en este navegador. No detecta tu ubicación real.</p></section><section class="card"><div class="row between"><h3>Estaciones de tu trayecto</h3><span class="pill">${stops.length} paradas</span></div><div class="stop-key"><span>✓ Recorrida</span><span>● Última alcanzada</span><span>○ Pendiente</span></div><ol class="journey-stops">${stops.map((s,i)=>`<li data-journey-stop="${i}"><span class="stop-marker">${i+1}</span><div><strong>${esc(s.name)}</strong><small>${esc(s.line)}${s.transfer?' · Cambia a '+esc(s.transfer):''}</small><span class="stop-status"></span></div></li>`).join('')}</ol>${r.accessTo?`<p>Al bajar, continúa hacia <strong>${esc(r.accessTo.name)}</strong>. Distancia en línea recta: ${distanceLabel(r.walkTo)}.</p>`:''}</section></div><div class="stack journey-side">${journeyMap(r)}<section class="card"><span class="pill green">Pasaje de ejemplo registrado</span><p>${money(r.cost)} · ${esc(r.cardName)}</p><button class="primary full" onclick="endJourney()">Terminar viaje</button><button class="text-btn spaced" onclick="go('plan')">Consultar otro recorrido</button></section></div></div>`}
referenceTrip=function(r){if(data.active)return activeJourneyView(r);return flowNav('trip')+`<button class="text-btn" onclick="go('plan')">← Volver a mis opciones</button>`+(r.accessFrom?`<div class="access-summary"><strong>${esc(r.accessFrom.name)} → ${esc(r.accessTo.name)}</strong><p>Acceso a ${esc(r.origin)}: ${distanceLabel(r.walkFrom)}. Desde ${esc(r.destination)} al destino: ${distanceLabel(r.walkTo)}. Distancias en línea recta; revisa cruces y accesos en el lugar.</p></div>`:'')+originalTripDetails(r)};
const originalStart=startTrip;startTrip=function(){const wasActive=!!data.active;originalStart();if(!wasActive&&data.active){data.active.progress=0;journeyRunning=true;save();render()}};
function nextJourneyStop(){if(!data.active)return;const {stops,index}=progressState(data.active);data.active.progress=Math.min(1,(index+1)/(stops.length-1));save();paintJourney()}
function paintJourney(){if(!data.active)return;const {stops,progress,index,position}=progressState(data.active),el=document.getElementById('journey-status');if(!el)return;el.textContent=progress===1?'Llegaste a '+stops.at(-1).name:'Última estación: '+stops[index].name;document.getElementById('journey-next').textContent=progress===1?'Completaste el recorrido simulado.':'Siguiente: '+stops[index+1].name;document.getElementById('journey-bar').style.width=progress*100+'%';document.getElementById('journey-count').textContent=index+' de '+(stops.length-1)+' tramos completados';document.getElementById('journey-percent').textContent=Math.floor(progress*100)+'%';const alert=document.getElementById('journey-alert');alert.textContent=progress===1?'✓ Llegaste. Puedes terminar tu viaje.':index===stops.length-2?'Tu destino es la siguiente parada. Prepárate para bajar.':stops[index].transfer?'Transbordo: continúa en '+stops[index].transfer+'.':'';alert.hidden=!alert.textContent;document.querySelectorAll('[data-journey-stop]').forEach((li,i)=>{li.className=i<index?'completed':i===index?'current':'upcoming';li.querySelector('.stop-marker').textContent=i<index?'✓':i===index?'●':i+1;li.querySelector('.stop-status').textContent=i<index?'Recorrida':i===index?(progress===1?'Destino alcanzado':'Última alcanzada'):'Por recorrer';if(i===index)li.setAttribute('aria-current','step');else li.removeAttribute('aria-current')});const a=simPoint(index,stops.length),b=simPoint(Math.min(index+1,stops.length-1),stops.length),f=position-index,p={x:a.x+(b.x-a.x)*f,y:a.y+(b.y-a.y)*f};document.getElementById('journey-bus').setAttribute('transform',`translate(${p.x},${p.y})`);document.getElementById('journey-line').setAttribute('points',[...stops.slice(0,index+1).map((_,i)=>simPoint(i,stops.length)),p].map(x=>x.x+','+x.y).join(' '));document.querySelectorAll('[data-journey-dot]').forEach((d,i)=>d.setAttribute('fill',i<=index?'#0b5aa8':'white'));document.getElementById('journey-next-button').disabled=progress===1;if(progress===1){journeyRunning=false;const button=document.getElementById('journey-play');button.disabled=true;button.textContent='Recorrido completado'}}
function endJourney(){if(!data.active)return;if((data.active.progress||0)<1)modal(`<h2>¿Terminar antes de llegar?</h2><p>El seguimiento se cerrará. El gasto de ejemplo ya registrado se conserva.</p><button class="primary full" onclick="closeModal();journeyRunning=false;finishTrip()">Sí, terminar viaje</button><button class="secondary full spaced" onclick="closeModal()">Seguir mi viaje</button>`);else{journeyRunning=false;finishTrip()}}
const originalTrip=trip;trip=function(){if(!data.active&&!lastRoute)return flowNav('trip')+heading('Tu próximo viaje te espera.','Planifica una ruta para seguir las estaciones que recorres.')+`<section class="card empty-trip">${icon('route')}<h2>Todo tu trayecto en un solo lugar</h2><p>Ve qué paradas completaste, cuál sigue y cuándo debes bajar.</p><button class="primary" onclick="go('plan')">Planificar mi viaje →</button></section>`;return originalTrip()};
liveRouteView=function(){return flowNav('live')+originalLive().replace('Tu ruta, parada a parada.','Rutas y horarios.').replace('Consulta los recorridos y horarios. Prueba el avance del bus en modo demostración.','Explora los servicios. Para seguir tus paradas, inicia un viaje desde Planificar.')};
const originalPlanFromService=planFromService;planFromService=function(id,dir){planMode='stops';originalPlanFromService(id,dir)};
const previousRender=render;render=function(){if(geoMap){geoMap.remove();geoMap=null;geoLayers=null}clearInterval(journeyTimer);previousRender();mountMap();if(page==='trip'&&data.active?.legs){paintJourney();journeyTimer=setInterval(()=>{if(!journeyRunning||!data.active)return;const old=progressState(data.active).index;data.active.progress=Math.min(1,(data.active.progress||0)+.0015*journeySpeed);paintJourney();if(old!==progressState(data.active).index||data.active.progress===1)save()},100)}};
const previousGo=go;go=function(p){if(data.active)save();previousGo(p)};
about=function(){modal(`<h2>Planifica y sigue tu viaje</h2><p>Este prototipo usa rutas proporcionadas por la usuaria y 44 puntos de referencia de OpenStreetMap consultados mediante Photon el 10 de noviembre de 2026. Ramón Castilla usa el punto de la plaza como aproximación. No son entradas verificadas a las estaciones.</p><p>El mapa compara servicios del Metropolitano y accesos en línea recta. Los corredores se consultan por paradas. El catálogo es parcial: no garantiza el camino más corto de Lima ni comprueba operación a una hora concreta.</p><p>La búsqueda de direcciones usa un servicio externo. Los saldos, gastos y el avance se guardan solo en este navegador. El movimiento, los tiempos y pagos son simulados, sin GPS.</p><a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">© OpenStreetMap contributors · ODbL</a>`)};
render();
